import { Physics, Spine } from '@esotericsoftware/spine-pixi-v8';
import { Bounds, Container, Graphics, Point, Renderer, RenderTexture } from 'pixi.js';

enum TintState {
    FROZEN = 'frozen',
    IDLE = 'idle',
    ANIMATING = 'animating'
}

enum DebugColors {
    FROZEN = 0x0000ff,
    IDLE = 0xff0000,
    ANIMATING = 0x88ff88
}

interface SpineHistory {
    vertices: number[];
    pixelHash?: string;
    lastTintState?: TintState;
    frozen: boolean;
}

interface AnimationTrack {
    animation?: unknown;
    timeScale?: number;
    loop?: boolean;
    isComplete?: () => boolean;
}

interface HighlighterConfig {
    frozenCheckInterval?: number;
    maxTextureSize?: number;
    minTextureSize?: number;
    textureScaleFactor?: number;
    alphaThreshold?: number;
    debugOutlineThickness?: number;
    debugRectangleThickness?: number;
    debugRectangleAlpha?: number;
    borderThickness?: number;
    crossCenterSize?: number;
    hashLengthDifferenceThreshold?: number;
    hashComparisonLength?: number;
}

const DEFAULT_CONFIG: Required<HighlighterConfig> = {
    frozenCheckInterval: 24,
    maxTextureSize: 64,
    minTextureSize: 1,
    textureScaleFactor: 0.8,
    alphaThreshold: 0.05,
    debugOutlineThickness: 4,
    debugRectangleThickness: 8,
    debugRectangleAlpha: 0.8,
    borderThickness: 8,
    crossCenterSize: 20,
    hashLengthDifferenceThreshold: 100,
    hashComparisonLength: 200
};

export class SpineIdleHighlighter {
    private spineHistory: WeakMap<Spine, SpineHistory> = new WeakMap();
    private spineFrameCounter: WeakMap<Spine, number> = new WeakMap();
    private spineCheckOffset: WeakMap<Spine, number> = new WeakMap();
    private renderer: Renderer;
    private config: Required<HighlighterConfig>;

    private running: boolean = true;

    constructor(renderer: Renderer, config: HighlighterConfig = {}) {
        if (!renderer) {
            throw new Error('Renderer is required for SpineIdleHighlighter');
        }
        this.renderer = renderer;
        this.config = { ...DEFAULT_CONFIG, ...config };
    }

    /**
     * Simple hash comparison that's more tolerant to minor differences
     */
    private hashesAreEquivalent(hash1: string, hash2: string): boolean {
        if (hash1 === hash2) return true;
        // If hashes are very similar length, they might be equivalent
        const lengthDifference = Math.abs(hash1.length - hash2.length);
        if (lengthDifference > this.config.hashLengthDifferenceThreshold) return false;
        // Compare last 200 characters
        return hash1.slice(-this.config.hashComparisonLength) === hash2.slice(-this.config.hashComparisonLength);
    }

    /**
     * Checks if a spine is visually frozen by comparing base64-encoded pixel data
     */
    private isSpineFrozen(spine: Spine, globalFrame: number): boolean {
        // Stagger freeze checks for performance
        if (!this.spineCheckOffset.has(spine)) {
            this.spineCheckOffset.set(spine, Math.floor(Math.random() * this.config.frozenCheckInterval));
        }
        const offset = this.spineCheckOffset.get(spine) ?? 0;
        if ((globalFrame + offset) % this.config.frozenCheckInterval !== 0) {
            return this.spineHistory.get(spine)?.frozen ?? false;
        }

        let frozen = false;
        try {
            const currentHash = this.getSpineHash(spine);
            const previousPixelHash = this.spineHistory.get(spine)?.pixelHash;
            if (previousPixelHash !== undefined) {
                frozen = this.hashesAreEquivalent(previousPixelHash, currentHash);
            }
            this.spineHistory.set(spine, {
                vertices: [],
                pixelHash: currentHash,
                lastTintState: this.spineHistory.get(spine)?.lastTintState,
                frozen
            });
        } catch (error) {
            console.warn('Failed to check if spine is frozen:', error);
            this.spineHistory.set(spine, {
                vertices: [],
                frozen: false
            });
        }
        this.spineFrameCounter.set(spine, globalFrame);
        return frozen;
    }

    /**
     * Gets the base64 hash of a spine's visual output
     */
    private getSpineHash(spine: Spine): string {
        try {
            const localBounds = spine.getLocalBounds();
            const width = Math.min(Math.max(Math.ceil(localBounds.width), this.config.minTextureSize), this.config.maxTextureSize);
            const height = Math.min(Math.max(Math.ceil(localBounds.height), this.config.minTextureSize), this.config.maxTextureSize);
            const renderTexture = RenderTexture.create({ width, height });
            const temporaryContainer = new Container();
            const originalParent = spine.parent;
            const originalIndex = originalParent ? originalParent.getChildIndex(spine) : -1;
            if (originalParent) originalParent.removeChild(spine);
            const originalTransform = {
                x: spine.x,
                y: spine.y,
                scaleX: spine.scale.x,
                scaleY: spine.scale.y,
                rotation: spine.rotation
            };
            // Save and reset tint
            const hasTint = 'tint' in spine;
            const originalTint = hasTint ? spine.tint : 0xffffff;
            if (hasTint) spine.tint = 0xffffff;
            spine.x = width / 2;
            spine.y = height / 2;
            spine.scale.set(Math.min(width / localBounds.width, height / localBounds.height) * this.config.textureScaleFactor);
            spine.rotation = 0;
            temporaryContainer.addChild(spine);
            if (spine.skeleton && typeof spine.skeleton.updateWorldTransform === 'function') {
                spine.skeleton.updateWorldTransform(Physics.update);
            }
            this.renderer.render({ container: temporaryContainer, target: renderTexture, clear: true });
            const canvas = this.renderer.extract.canvas(renderTexture);
            const pixelHash = canvas.toDataURL?.('image/png') ?? '';
            // Restore original spine transform, parent, and tint
            spine.x = originalTransform.x;
            spine.y = originalTransform.y;
            spine.scale.set(originalTransform.scaleX, originalTransform.scaleY);
            spine.rotation = originalTransform.rotation;
            if (hasTint) spine.tint = originalTint;
            temporaryContainer.removeChild(spine);
            if (originalParent && originalIndex >= 0) {
                originalParent.addChildAt(spine, originalIndex);
            }
            renderTexture.destroy(true);
            return pixelHash;
        } catch (error) {
            console.warn('Failed to generate spine hash:', error);
            return '';
        }
    }

    /**
     * Draws a debug rectangle on the debug layer
     */
    private drawDebugRectangle(debugLayer: Graphics, bounds: Bounds, color: number): void {
        debugLayer
            .rect(bounds.x, bounds.y, bounds.width, bounds.height)
            .stroke({ width: this.config.debugRectangleThickness, color, alpha: this.config.debugRectangleAlpha });
    }

    /**
     * Type guard to check if an object is a Spine display object
     */
    private isSpineObject(obj: unknown): obj is Spine & Container {
        return obj !== null && typeof obj === 'object' &&
            'skeleton' in obj &&
            'state' in obj &&
            'getBounds' in obj && typeof (obj as Record<string, unknown>).getBounds === 'function' &&
            'visible' in obj &&
            'renderable' in obj &&
            'tint' in obj &&
            'alpha' in obj;
    }

    /**
     * Cleans up all stored data and resets the highlighter
     */
    public cleanup(): void {
        this.spineHistory = new WeakMap();
        this.spineFrameCounter = new WeakMap();
        this.spineCheckOffset = new WeakMap();
    }

    public stopHighlights(
        container: Container,
        debugLayer: Graphics
    ): void {
        this.running = false;
        debugLayer.clear();
        this.clearChildTints(container);
    }

    private clearChildTints(child: Container): void {
        if (this.isSpineObject(child)) {
            child.tint = 0xffffff;
        }

        if (child instanceof Container && child.children.length > 0) {
            child.children.forEach(element => {
                this.clearChildTints(element);
            });
        }
    }

    /**
     * Finds idle or frozen spines and highlights them.
     * @param container - Root container to scan.
     * @param debugLayer - Shared graphics object for drawing highlights.
     * @param globalFrame - Current frame number.
     */
    public highlightIdleSpines(
        container: Container,
        debugLayer: Graphics,
        globalFrame: number
    ): void {
        if (!this.running) {
            return;
        }
        container.children.forEach((child: Container) => {
            // Draw outline for nearly invisible spines (consider cumulative alpha and draw on correct parent)
            if (this.isSpineObject(child) && child.visible && child.renderable && child.parent) {
                // Check if any parent in the chain is not visible or not renderable
                let isParentChainVisible = true;
                let parent: Container | null = child.parent;
                while (parent && isParentChainVisible) {
                    if ('visible' in parent && !parent.visible) {
                        isParentChainVisible = false;
                    }
                    if ('renderable' in parent && !parent.renderable) {
                        isParentChainVisible = false;
                    }
                    parent = parent.parent;
                }

                // Skip if parent chain is not visible/renderable
                if (!isParentChainVisible) {
                    return;
                }

                let effectiveAlpha = child.alpha;
                let drawParent: Container = child.parent;
                let currentParent: Container | null = child.parent;
                while (currentParent) {
                    if ('alpha' in currentParent) {
                        effectiveAlpha *= (currentParent as Container).alpha;
                        if (effectiveAlpha < this.config.alphaThreshold && currentParent instanceof Container) {
                            drawParent = currentParent;
                        }
                    }
                    currentParent = currentParent.parent;
                }
                if (effectiveAlpha < this.config.alphaThreshold && drawParent) {
                    const Container = child as Spine & Container;
                    const bounds = Container.getBounds();
                    // Convert global bounds to drawParent local coordinates
                    const origin = debugLayer.toLocal(new Point(0, 0), Container);
                    debugLayer.circle(origin.x, origin.y, 10).fill({ color: 0x00ff00 });

                    debugLayer.rect(bounds.x, bounds.y, bounds.width, bounds.height).stroke({ width: 5, color: 0xffff00, alpha: 1 });
                }
            }
            // Only highlight/tint Spine-like objects that are not animating or are frozen
            if (this.isSpineObject(child)) {
                const Container = child as Spine & Container;
                const isVisible = Container.visible;
                const state = Container.state;
                // Check if actively animating: either non-looped active track OR looped track with positive timeScale
                const hasActiveAnimation = state && Array.isArray(state.tracks) && state.tracks.some((track: AnimationTrack | null) =>
                    track && track.animation && (track.timeScale ?? 0) > 0 &&
                    (track.loop || (track.isComplete ? !track.isComplete() : false))
                );
                const frozen = this.isSpineFrozen(Container, globalFrame);
                if (isVisible) {
                    const bounds = Container.getBounds();
                    let currentTintState: TintState;
                    if (frozen) {
                        currentTintState = TintState.FROZEN;
                    } else if (!hasActiveAnimation) {
                        currentTintState = TintState.IDLE;
                    } else {
                        currentTintState = TintState.ANIMATING;
                    }
                    // Only change tint if state has actually changed
                    const history = this.spineHistory.get(Container);
                    const lastTintState = history?.lastTintState;
                    if (lastTintState !== currentTintState) {
                        if (currentTintState === TintState.FROZEN) {
                            Container.tint = DebugColors.FROZEN;
                            this.drawDebugRectangle(debugLayer, bounds, DebugColors.FROZEN);
                        } else if (currentTintState === TintState.IDLE) {
                            Container.tint = DebugColors.IDLE;
                            this.drawDebugRectangle(debugLayer, bounds, DebugColors.IDLE);
                        } else if (currentTintState === TintState.ANIMATING) {
                            Container.tint = DebugColors.ANIMATING;
                        }
                        if (history) {
                            history.lastTintState = currentTintState;
                        }
                    } else {
                        if (currentTintState === TintState.FROZEN) {
                            this.drawDebugRectangle(debugLayer, bounds, DebugColors.FROZEN);
                        } else if (currentTintState === TintState.IDLE) {
                            this.drawDebugRectangle(debugLayer, bounds, DebugColors.IDLE);
                        }
                    }
                }
            }
            if (child instanceof Container && child.children.length > 0) {
                this.highlightIdleSpines(child, debugLayer, globalFrame);
            }
        });
    }
}
